    'faq_note' => 'תשובות לשאלות נפוצות.',
    'faq_q1' => '<strong>מה זה TropaTT?</strong><br>פלטפורמת CRM, מנהל משימות וניהול פרויקטים, המתארח בעצמו בקוד פתוח בחינם.',
