    'faq_q10_answer' => '<strong>אנטון בארינוב</strong>, מפתח PHP.',
    'faq_q2' => '<strong>האם זה CRM או מנהל משימות?</strong><br>שניהם. CRM עבור לקוחות וצדדים נגדיים, מנהל משימות עבור משימות, בתוספת ניהול פרויקטים, צ\'אט, לוח שנה ובינה מלאכותית.',
    'faq_q3' => '<strong>האם זה מתאים לפרילנסרים?</strong><br>כן. אין גודל מינימום של צוות. משתמש יחיד מקבל CRM, משימות, תוכנית יום בינה מלאכותית וצ\'אט ללא עמלות לכל מושב.',
