    'faq_q5' => '<strong>האם יש מגבלות על משתמשים ומשימות?</strong><br>לא. משתמשים, משימות, פרויקטים ולקוחות ללא הגבלה. המגבלה היחידה היא קיבולת השרת.',
    'faq_q6' => '<strong>היכן מאוחסנים הנתונים?</strong><br>100% בשרת שלך. המערכת אף פעם לא מסנכרנת נתונים לענן.',
    'faq_q7' => '<strong>אילו כלי בינה מלאכותית זמינים?</strong><br>20+ כלים: חקר רעיונות, תוכניות יום/שבוע, סיכומים, רשימות ביקורת, סיכונים, הכנה לפגישה.',
