    'mcp_title' => 'סוכני בינה מלאכותית (MCP)',
    'mcp_note' => 'חבר את Claude Code, Codex, ChatGPT וסוכני AI אחרים ל-CRM.',
    'mcp_why' => '<strong>למה:</strong> MCP מאפשר לסוכני AI לקרוא ולנהל את המשימות, הפרויקטים, הלקוחות והצ\'אטים שלך באמצעות פרוטוקול מאוחד - עם אותן הרשאות גישה כמו ממשק המשתמש האינטרנטי.',
    'mcp_intro' => 'TropaTT כולל שרת MCP (Model Context Protocol) מובנה - אותו פרוטוקול המובן על ידי Claude Code, Codex, ChatGPT וסוכני AI תואמים אחרים.',
    'mcp_item1' => '<strong>620 כלי MCP + 6 משאבים</strong> - משימות, פרויקטים, לקוחות, אנשי קשר, צ\'אטים, לוח שנה, ניתוח, בסיס ידע.',
    'mcp_item2' => '<strong>אותם נתונים וכללים</strong> - כל בקשה עוברת בדיקות REST API ו-RBAC, בדיוק כמו ממשק האינטרנט.',
    'mcp_item3' => '<strong>אבטחה</strong> - נתונים רגישים (אסימונים, גיבוב סיסמאות, מפתחות API) מסוננים; כתיבה דורשת הרשאות מתאימות.',
    'mcp_item4' => '<strong>נקודת קצה:</strong> POST /api/index.php?route=api/v1/mcp, אימות באמצעות Token Bearer.',
    'mcp_docs_link' => 'תיעוד MCP מלא:',
    'usage_title' => 'דוגמאות לשימוש',
    'usage_note' => 'תרחישים קונקרטיים לתפקידים ותעשיות שונות.',
    'usage_why' => '<strong>למה:</strong> דוגמאות אלו מראות כיצד נעשה שימוש ב-TropaTT בזרימות עבודה אמיתיות - החל מבקשה נכנסת ועד למשימה שהושלמה.',
    'usage_cycle_heading' => 'מחזור עבודה מלא של הלקוח',
    'usage_step1' => '<strong>לכידה</strong> - רעיון, בקשת לקוח, בעיה או הפניה נכנסת.',
    'usage_step2' => '<strong>ניתוח</strong> - לבד או עם AI: היקף, סיכונים, היתכנות, גישה.',
    'usage_step3' => '<strong>מבנה</strong> - לתוך פרויקטים, משימות, משימות משנה, רשימות תיוג, מוקצים, מועדים.',
    'usage_step4' => '<strong>תיאום</strong> - באמצעות צ\'אט, הערות, @אזכורים, התראות.',
    'usage_step5' => '<strong>ביצוע</strong> - רשימות משימות, Kanban, My Day, My Week.',
    'usage_step6' => '<strong>מעקב</strong> - גאנט, לוחות מחוונים, ניתוחים, עומס, אותות סיכון.',
    'usage_step7' => '<strong>אוטומציה</strong> - כללי זרימת עבודה, SLA, webhooks, שרשראות אישורים.',
    'usage_examples_heading' => 'דוגמאות קונקרטיות',
    'usage_ex1' => '<strong>פרילנסר:</strong> בקשת לקוח → ניתוחי בינה מלאכותית → תוכנית משימות → היום שלי → ביצוע → צ\'אט לקוח → בוצע.',
    'usage_ex2' => '<strong>סוכנות:</strong> תקציר לקוח → AI מפרק → פרויקט + אבני דרך → Kanban → מעקב גנט → דוח לקוח → ניתוח.',
    'usage_ex3' => '<strong>חברת שירות:</strong> צד נגדי → פרויקט → משימות התקנה → Gantt → תוכניות יומיות → ניטור SLA → חתימת אקט.',
    'usage_ex4' => '<strong>פעולות B2B:</strong> חברה → אנשי קשר → משימות + אישורים → תזכורות → webhook → לוח מחוונים.',
    'tech_title' => 'טכנולוגיות ומספרים',
    'tech_note' => 'ערימה, ארכיטקטורה ומדדי מפתח של פרויקטים.',
    'tech_why' => '<strong>למה:</strong> הבנת המחסנית עוזרת להעריך את דרישות האירוח, אפשרויות התאמה אישית ומדרגיות המערכת.',
    'tech_stack_heading' => 'מחסנית טכנולוגיה',
    'tech_stack1' => '<strong>גב:</strong> PHP 8.1+, מיקרו-קרנל מותאם אישית. אפס תלות חיצונית. ללא Laravel / סימפוניה / דוקטרינה.',
    'tech_stack2' => '<strong>מסד נתונים:</strong> MySQL.',
    'tech_stack3' => '<strong>חזית:</strong> MPA בעיבוד PHP + Bootstrap 5 + מודולים מותאמים אישית וניל JS ES5+. No React/Vue/Angular. אין צרור.',
    'tech_stack4' => '<strong>ארכיטקטורה:</strong> תחילה API. ממשק המשתמש באינטרנט משתמש ב- REST API עבור כל הנתונים. אפס קריאות DB ישירות משכבת ​​האינטרנט.',
    'tech_stack5' => '<strong>אבטחה:</strong> אימות כפול (cookie + CSRF לאינטרנט, Bearer עבור API). RBAC. הגנת SSRF. הגבלת שיעור.',
    'tech_stack6' => '<strong>AI:</strong> ספקים הניתנים להגדרה (OpenAI, Anthropic, DeepSeek, Google). זרימות עבודה של כוונה. תצוגה מקדימה-לפני-החלה.',
